<?php
declare(strict_types=1);require_once __DIR__.'/auth.php';require_login();$pdo=db();if(!table_exists($pdo,'exceptions'))redirect('upgrade_phase6.php');$msg=flash('success');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=post_string('action');$id=post_int('id');if($action==='add'){$title=post_string('title');if($title){$s=$pdo->prepare('INSERT INTO exceptions(module,severity,title,description,assigned_user_id) VALUES(?,?,?,?,?)');$s->execute([post_string('module','general'),post_string('severity','medium'),$title,post_string('description')?:null,post_int('assigned_user_id')?:null]);activity($pdo,'create','exceptions',$pdo->lastInsertId(),'Exception created');flash('success','Exception recorded.');}}elseif($action==='resolve'){$pdo->prepare('UPDATE exceptions SET status="resolved",resolved_by=?,resolved_at=NOW() WHERE id=?')->execute([current_user()['id'],$id]);activity($pdo,'resolve','exceptions',$id,'Exception resolved');flash('success','Exception resolved.');}redirect('exceptions.php');}
$users=$pdo->query("SELECT id,first_name,last_name FROM users WHERE status='active' ORDER BY first_name")->fetchAll();$rows=$pdo->query("SELECT e.*,TRIM(CONCAT(COALESCE(u.first_name,''),' ',COALESCE(u.last_name,''))) assigned_name FROM exceptions e LEFT JOIN users u ON u.id=e.assigned_user_id ORDER BY e.id DESC LIMIT 200")->fetchAll();?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Exceptions</title><style>body{margin:0;background:#f5f7fb;font-family:Arial;color:#172033}.top{background:#fff;padding:18px 28px;border-bottom:1px solid #e5eaf2}.wrap{max-width:1150px;margin:auto;padding:28px}.grid{display:grid;grid-template-columns:1fr 1.7fr;gap:16px}.card{background:#fff;border:1px solid #e5eaf2;border-radius:15px;padding:20px}.field{margin:10px 0}.field label{display:block;font-size:12px;font-weight:800;margin-bottom:6px}.field input,.field select,.field textarea{width:100%;padding:10px;border:1px solid #d8dfeb;border-radius:8px;box-sizing:border-box}.btn{background:#315ee7;color:#fff;border:0;padding:9px 12px;border-radius:8px;font-weight:800}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:10px;border-bottom:1px solid #edf0f5;text-align:left;font-size:13px}@media(max-width:820px){.grid{grid-template-columns:1fr}}</style></head><body><header class="top"><b>SPS CRM · Exceptions</b> · <a href="dashboard.php">Dashboard</a></header><main class="wrap"><?php if($msg):?><p><?=e($msg)?></p><?php endif;?><div class="grid"><div class="card"><h2>Record Exception</h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="add"><div class="field"><label>Title</label><input name="title" required></div><div class="field"><label>Module</label><input name="module" value="service"></div><div class="field"><label>Severity</label><select name="severity"><option>low</option><option selected>medium</option><option>high</option><option>critical</option></select></div><div class="field"><label>Description</label><textarea name="description"></textarea></div><div class="field"><label>Assign</label><select name="assigned_user_id"><option value="">Unassigned</option><?php foreach($users as $u):?><option value="<?=$u['id']?>"><?=e($u['first_name'].' '.$u['last_name'])?></option><?php endforeach;?></select></div><button class="btn">Record Exception</button></form></div><div class="card"><h2>Exception Queue</h2><table class="table"><tr><th>Severity</th><th>Title</th><th>Assigned</th><th>Status</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['severity'])?></td><td><?=e($r['title'])?></td><td><?=e($r['assigned_name']?:'Unassigned')?></td><td><?=e($r['status'])?></td><td><?php if($r['status']!=='resolved'):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="resolve"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn">Resolve</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></div></main></body></html>
